/**
 * @name Trace pickle.load source
 * @description Trace where the file object passed to pickle.load comes from
 * @kind path-problem
 * @problem.severity error
 * @id py/trace-pickle-source
 * @tags security
 *       external/cwe/cwe-502
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.ApiGraphs

module PickleSourceConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    // Source is the return value of an open() call
    source = API::builtin("open").getACall()
  }

  predicate isSink(DataFlow::Node sink) {
    // Sink is the argument to pickle.load
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("pickle").getMember("load").getACall() and
      sink = call.getArg(0)
    )
  }
}

module PickleSourceFlow = TaintTracking::Global<PickleSourceConfig>;
import PickleSourceFlow::PathGraph

from PickleSourceFlow::PathNode source, PickleSourceFlow::PathNode sink
where PickleSourceFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "pickle.load uses file from $@", source.getNode(), "open()"

/**
 * @name Trace file path source in fetchers
 * @description Traces where the file path argument to open() comes from in scipy/datasets/_fetchers.py
 * @kind path-problem
 * @problem.severity warning
 * @id py/trace-fetchers-path
 * @tags security
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.ApiGraphs

module FetcherPathConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    // We want to see where the path comes from, so we'll treat parameters of functions in this file as sources
    // or return values of other functions.
    source instanceof DataFlow::ParameterNode
    or
    source = API::moduleImport("scipy").getMember("datasets").getMember("_registry").getMember("registry").getMember("get").getACall()
    or
    source = API::moduleImport("pooch").getMember("retrieve").getACall()
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      call = API::builtin("open").getACall() and
      call.getLocation().getFile().getShortName() = "_fetchers.py" and
      sink = call.getArg(0)
    )
  }
}

module FetcherPathFlow = TaintTracking::Global<FetcherPathConfig>;
import FetcherPathFlow::PathGraph

from FetcherPathFlow::PathNode source, FetcherPathFlow::PathNode sink
where FetcherPathFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "File path from $@ flows to open().", source.getNode(), "source"
